 insert into public.shooting_lanes(id,tenant_id,name,type,is_active,max_shooters,booking_step_minutes,display_order,currency_code,resource_kind,whole_lane_bookable,positions_bookable)values(lane,t,'PAM lane','test',true,2,60,901,'PLN','lane',true,false);
 insert into public.lane_blocks(tenant_id,lane_id,block_date,start_time,end_time,reason,is_active)values(t,lane,current_date-10,'10:00','11:00','Historical',true);
