 r:=pg_temp.rpc(pa,format('select public.platform_change_tenant_plan_v2(%L,''current_full_v1'',''3'',%L)',t,gen_random_uuid()));
 perform pg_temp.assert_true('upgrade after explicit visibility review allowed',r->>'state'='00000');
 r:=pg_temp.rpc(other_user,format('select public.admin_create_event_v3(%L,''Cancellation probe'',null,current_date+12,''10:00'',''11:00'',''Local'',0,10,''{}'')',t));
 e:=(r->'value'->>'event_id')::uuid;
 perform pg_temp.assert_true('cancellation fixture real event RPC',r->'value'->>'ok'='true');
 perform set_config('app.product10d_test_enforce','off',true);
 insert into public.event_registrations(tenant_id,event_id,user_id,customer_name,customer_email,customer_phone,registration_status,payment_status)values(t,e,other_user,'Local cancel','cancel@example.invalid','000','registered','free');
 perform set_config('app.product10d_test_enforce','on',true);
 r:=pg_temp.rpc(other_user,format('select public.admin_cancel_event_v1(%L)',e));
 perform pg_temp.assert_true('event cancellation real RPC',r->>'state'='00000' and r->'value'->>'code'='cancelled');
 p:=pg_temp.rpc(pa,format('select public.platform_get_tenant_plan_change_preview_v1(%L,''booking_only_v1'')',t))->'value';
 perform pg_temp.assert_true('cancelled event pending notification blocks',p->'blockers' @> '[{"code":"EVENT_EMAIL_OBLIGATIONS"}]');
 perform pg_temp.assert_true('cancelled event no future active-event blocker',not(p->'blockers' @> '[{"code":"EVENTS_OPEN"}]'));
 perform set_config('app.product10d_test_enforce','off',true);
 update public.tenant_memberships set role='employee' where tenant_id=t and user_id=other_user;
 perform pg_temp.assert_true('employee cannot preview',pg_temp.rpc(other_user,format('select public.platform_get_tenant_plan_change_preview_v1(%L,''booking_only_v1'')',t))->>'state'='42501');
 perform pg_temp.assert_true('employee cannot write',pg_temp.rpc(other_user,format('select public.platform_change_tenant_plan_v2(%L,''current_full_v1'',''4'',%L)',t,gen_random_uuid()))->>'state'='42501');
 update public.tenant_memberships set role='instructor' where tenant_id=t and user_id=other_user;
 perform pg_temp.assert_true('instructor cannot write',pg_temp.rpc(other_user,format('select public.platform_change_tenant_plan_v2(%L,''current_full_v1'',''4'',%L)',t,gen_random_uuid()))->>'state'='42501');
 update public.tenant_memberships set role='user' where tenant_id=t and user_id=other_user;
 perform pg_temp.assert_true('user cannot write',pg_temp.rpc(other_user,format('select public.platform_change_tenant_plan_v2(%L,''current_full_v1'',''4'',%L)',t,gen_random_uuid()))->>'state'='42501');

 update public.platform_admins set status='suspended' where user_id=pa;
 perform pg_temp.assert_true('suspended PA denied',pg_temp.rpc(pa,q)->>'state'='42501'); delete from public.platform_admins where user_id=pa; perform pg_temp.assert_true('removed PA denied',pg_temp.rpc(pa,q)->>'state'='42501');
end;$test$;

do $matrix$
declare d public.email_deliveries; kind text;
begin
 foreach kind in array array['event_reserve_acceptance_confirmation','event_registration_cancellation','event_cancellation','instructor_assignment','instructor_removal','instructor_event_cancellation','event_reminder_24h'] loop
  d:=jsonb_populate_record(null::public.email_deliveries,jsonb_build_object('message_type',kind,'delivery_state','pending','attempt_count',0));
  perform pg_temp.assert_true(kind||' pending blocks',public.plan_change_email_is_open_v1(d));
  d.delivery_state:='sending';d.attempt_count:=3;d.claim_id:=gen_random_uuid();d.claim_expires_at:=statement_timestamp()+interval '5 minutes';
  perform pg_temp.assert_true(kind||' active final lease blocks',public.plan_change_email_is_open_v1(d));
  d.claim_id:=null;d.claim_expires_at:=null;d.delivery_state:='failed';d.attempt_count:=1;d.attempt_window_started_at:=statement_timestamp();d.last_error_code:='delivery_failed_or_uncertain';
  perform pg_temp.assert_true(kind||' retryable failure blocks',public.plan_change_email_is_open_v1(d));
  d.attempt_count:=3;d.last_error_code:='retry_exhausted';
  perform pg_temp.assert_true(kind||' exhausted failure excluded',not public.plan_change_email_is_open_v1(d));
  d.attempt_count:=1;d.attempt_window_started_at:=statement_timestamp()-interval '24 hours';
  perform pg_temp.assert_true(kind||' expired window matches actual claim contract',public.plan_change_email_is_open_v1(d)=(kind='event_reminder_24h'));
  d.delivery_state:='sent';d.sent_at:=statement_timestamp();
  perform pg_temp.assert_true(kind||' sent excluded',not public.plan_change_email_is_open_v1(d));
 end loop;
 d:=jsonb_populate_record(null::public.email_deliveries,'{"message_type":"event_reminder_24h","delivery_state":"failed","attempt_count":1,"last_error_code":"ineligible"}');
 perform pg_temp.assert_true('ineligible reminder terminal excluded',not public.plan_change_email_is_open_v1(d));
 d:=jsonb_populate_record(null::public.email_deliveries,'{"message_type":"event_registration_confirmation","attempt_count":3}');
 perform pg_temp.assert_true('legacy daily confirmation cap is not terminal',public.plan_change_email_is_open_v1(d));
 d.sent_at:=statement_timestamp();
 perform pg_temp.assert_true('legacy sent confirmation excluded',not public.plan_change_email_is_open_v1(d));
 perform pg_temp.assert_true('closed lifecycle helper no client execute',not has_function_privilege('authenticated','public.plan_change_email_is_open_v1(public.email_deliveries)','EXECUTE') and not has_function_privilege('anon','public.plan_change_email_is_open_v1(public.email_deliveries)','EXECUTE') and not has_function_privilege('service_role','public.plan_change_email_is_open_v1(public.email_deliveries)','EXECUTE'));
end;$matrix$;

